declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/estate_ui.php';
$admin=(int)$_SESSION['admin_id'];$account=(int)($_GET['account']??1);if(!in_array($account,[1,2],true))$account=1;$targetMonth=(string)($_GET['month']??date('Y-m'));try{$targetMonth=estateMonth($targetMonth);}catch(Throwable $e){$targetMonth=date('Y-m-01');}$back='estate_bank.php?account='.$account.'&month='.$targetMonth;$accounts=[];$transactions=[];$suggestions=[];$rentMatches=[];$proposal=null;$lists=['buildings'=>[],'units'=>[]];$documents=[];$ready=false;
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');if($action==='account')estateAccountSave($pdo,$admin,$account,$_POST);elseif($action==='preview'){if(empty($_POST['confirm_account']))throw new RuntimeException('Datei gehört zum ausgewählten Volksbank-Konto: ausdrücklich prüfen.');$f=$_FILES['statement']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('CSV-Upload maximal2MB.');$format=(string)($_POST['format']??'csv');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(($format==='camt'?'xml':'csv')!==$ext)throw new InvalidArgumentException('CSV-/XML-Dateiendung prüfen.');$map=['expected_iban'=>(string)($_POST['expected_iban']??'')];foreach(['booked_on','value_on','amount','currency','purpose','counterparty','id'] as $key)$map[$key]=opsText($_POST,'map_'.$key,190,$format==='csv'&&$key!=='value_on');$token=estateBankPreview($pdo,$admin,$account,file_get_contents($f['tmp_name']),$map,(string)($_POST['locale']??'de'),(string)($_POST['separator']??';'),$format);redirect($back.'&proposal='.$token);}
 elseif($action==='apply'){if(empty($_POST['confirm']))throw new RuntimeException('Import ausdrücklich bestätigen.');$count=estateBankApply($pdo,$admin,(string)($_POST['token']??''),!empty($_POST['possible_reviewed']));$_SESSION['app_notice']=$count.' neue Immobilienumsätze importiert. Keine Zuordnung/Buchung ausgelöst.';}
 elseif($action==='transfer'){if(empty($_POST['confirm']))throw new RuntimeException('Eigene Umbuchung bestätigen.');estatePairTransfer($pdo,$admin,estateId($_POST['outgoing_id']??0),estateId($_POST['incoming_id']??0),(string)($_POST['reason']??''));}
 elseif($action==='expense'){if(empty($_POST['confirm']))throw new RuntimeException('Ausgabenzuordnung bestätigen.');estateExpense($pdo,$admin,estateId($_POST['transaction_id']??0),estateId($_POST['building_id']??0),(int)($_POST['unit_id']??0),(string)($_POST['category']??''),(int)($_POST['document_id']??0),(string)($_POST['notes']??''));}
 else throw new RuntimeException('Aktion unbekannt.');if(!isset($_SESSION['app_notice']))$_SESSION['app_notice']='Immobilienkonten-Zuordnung gespeichert.';}catch(Throwable $e){gszUiError($e);}redirect($back);}
try{estateRequire($pdo);$accounts=$pdo->query('SELECT * FROM estate_bank_accounts ORDER BY id')->fetchAll();$q=$pdo->prepare('SELECT t.*,p.id payment_id,e.id expense_id,tr.id transfer_id FROM estate_bank_transactions t LEFT JOIN estate_payments p ON p.bank_transaction_id=t.id LEFT JOIN estate_expenses e ON e.transaction_id=t.id LEFT JOIN estate_transfers tr ON tr.outgoing_id=t.id OR tr.incoming_id=t.id WHERE t.account_id=? ORDER BY t.booked_on DESC,t.id DESC LIMIT 200');$q->execute([$account]);$transactions=$q->fetchAll();$suggestions=estateTransferSuggestions($pdo);$rentMatches=estateRentSuggestions($transactions,estateRentLedger($pdo,$targetMonth));$lists=estateLists($pdo);$documents=$pdo->query('SELECT id,original_name FROM estate_documents ORDER BY id DESC LIMIT 200')->fetchAll();if(isset($_GET['proposal'])){$q=$pdo->prepare("SELECT * FROM estate_proposals WHERE token=? AND admin_id=? AND kind='bank'");$q->execute([(string)$_GET['proposal'],$admin]);$proposal=$q->fetch();}$ready=true;}catch(Throwable $e){gszUiError($e);}estatePage('Zwei Volksbank-Konten');
